//! 🧪️ Original boxed Window leaves retain their exact source while native previews settle and cancel.
use super::*;
use crate::camera_owner::{IdentityWindowOwner,RetainedLoadCameraConfig,RetainedLoadCameraConfigMutation};
use semio_framework_value::{retained_clone::original_slot::RetainedOriginalSlot,retirement::controlled::ControlledRetirement};
fn granted(d:RetirementDemand)->RetainedCloneGrant{assert!(d.copy_bytes+d.capacity_bytes<=4096);RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth.max(1)}}
fn close_typed<T:semio_framework_value::retirement::RetireOwned>(original:T){let mut owner=ControlledRetirement::new(original).map_err(|(e,_)|e).unwrap();for _ in 0..65536{if owner.terminal_is_empty(){return;}let d=owner.next_demand(4096).unwrap();let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.step(granted(d)).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));}panic!("native preview original typed owner did not close");}
use crate::original_genesis_tests::{Owner,State,Mutation};
use semio_framework_job::{OriginalJobFixtureCaller,OriginalJobDecodeOwner,OriginalTurnFailure,StepContext,OperationId,Generation};
pub(crate) fn grant(d:RetirementDemand)->RetainedCloneGrant{assert!(d.copy_bytes<=4096&&d.capacity_bytes<=4096,"native Window preview quote exceeds declared body: {d:?}");RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth.max(1)}}
pub(crate) fn wide()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:65536,maximum_release_bytes:262144,maximum_depth:128}}
pub(crate) fn turn<T>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,g:RetainedCloneGrant,run:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->T{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(g,decoder,run));let receipt=caller.receipt();assert!(receipt.fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(receipt.retained_capacity_bytes,receipt.released_bytes));result.unwrap()}
pub(crate) fn typed_close<T:semio_framework_value::retirement::RetireOwned>(original:T,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner){let mut original=Some(original);let mut close=None;turn(caller,decoder,wide(),|cx|{let d=RetirementDemand{copy_bytes:2*size_of::<T>()+size_of::<ControlledRetirement<T>>(),depth:1,..Default::default()};semio_framework_job::close_original_retained_step(cx,d,|_|{close=Some(ControlledRetirement::new(original.take().unwrap()).map_err(|(e,_)|e).unwrap());Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;Ok(())});let close=close.as_mut().unwrap();for turn_index in 0..65536{if close.terminal_is_empty(){return;}let d=close.next_demand(4096).unwrap();turn(caller,decoder,grant(d),|cx|{semio_framework_job::close_original_retained_step(cx,d,|g|close.step(g))?;Ok(())});assert!(turn_index<65535,"original typed Window source failed to close");}}
fn advance(preview:&mut WindowSemanticPreview<Owner>,store:&WindowConfigStore<Owner>,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,g:RetainedCloneGrant)->RetainedCloneStep{turn(caller,decoder,g,|cx|{let d=preview.demand(store,4096)?;if !semio_framework_value::retained_clone::retained_clone_grant_admits(cx.retained_grant(),d){return Ok(RetainedCloneStep::Progress(Default::default()))}let result=cx.with_native_receiving(|receiving|preview.advance(store,4096,g,receiving));let progress=match &result{Ok(step)=>step.progress(),Err(error)=>error.retained_progress()};match cx.receiving_issued_grant(){Some(issued)=>cx.consume_receiving_retained(issued,progress)?,None=>cx.consume_retained(progress)?}cx.consume_fuel(progress.copied_items as u64);Ok(result?)})}
fn cancelled_leaf(store:&WindowConfigStore<Owner>,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,cut:usize){
 let mutation=WindowConfigMutation::of::<Owner>("original-preview-window",Mutation::Zoom{zoom:17.0});let pointer=mutation.mutation.as_any().downcast_ref::<Mutation>().unwrap()as*const Mutation;let mut slot=RetainedOriginalSlot::new(mutation);let key=slot.key();let factory:Arc<dyn store::ArtifactOwnedValueRetirementFactory<WindowConfigMutation>>=Arc::new(semio_framework_value::factory::OwnedValueRetirementFactory::<WindowConfigMutation>::default());
 while slot.borrow(key).is_err(){let d=slot.demands(key).unwrap();turn(caller,decoder,grant(d),|cx|{let p=slot.advance_read(key,&factory,grant(d))?.progress();cx.consume_retained(p)?;cx.consume_fuel(1);Ok(())});}
 let d=WindowSemanticPreview::<Owner>::birth_demand();let mut preview=turn(caller,decoder,grant(d),|cx|{let(owner,p)=WindowSemanticPreview::<Owner>::begin(store,grant(d))?.unwrap();cx.consume_retained(p)?;cx.consume_fuel(1);Ok(owner)});
 let d=RetainedOwnedProjection::<WindowConfigMutation>::constructor_demand();let mut input=turn(caller,decoder,grant(d),|cx|{let(input,p)=slot.retain_read(key,grant(d))?;cx.consume_retained(p)?;cx.consume_fuel(1);Ok(input)});let d=WindowSemanticPreview::<Owner>::input_demand();turn(caller,decoder,grant(d),|cx|{let p=preview.admit_input(&input,grant(d))?.unwrap();cx.consume_retained(p)?;cx.consume_fuel(1);Ok(())});while !input.terminal_is_empty(){let d=input.close_demand(4096).unwrap();turn(caller,decoder,grant(d),|cx|{semio_framework_job::close_original_retained_step(cx,d,|g|input.close_step(g))?;Ok(())});}
 for _ in 0..cut{let d=preview.demand(store,4096).unwrap();advance(&mut preview,store,caller,decoder,grant(d));}preview.cancel();for index in 0..65536{if preview.terminal_is_empty(){break;}let d=preview.demand(store,4096).unwrap();let g=grant(d);assert_eq!(advance(&mut preview,store,caller,decoder,RetainedCloneGrant{maximum_items:0,..g}).progress(),Default::default());advance(&mut preview,store,caller,decoder,g);assert!(index<65535,"cancelled native Window preview retained original owners at cut {cut}");}assert!(preview.terminal_is_empty());assert_eq!(slot.get().mutation.as_any().downcast_ref::<Mutation>().unwrap()as*const Mutation,pointer);typed_close(slot,caller,decoder);typed_close(semio_framework_value::FactoryAuthority::new(factory),caller,decoder);
}
#[test]
fn original_window_semantic_preview_matches_portable_outputs_and_retains_boxed_press_sources(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();
 for law in corpus["cases"].as_array().unwrap(){let mut caller=OriginalJobFixtureCaller::admit(OperationId(871),Generation(19),RetainedCloneGrant{maximum_items:1<<25,maximum_copy_bytes:1<<29,maximum_capacity_bytes:1<<27,maximum_release_bytes:1<<27,maximum_depth:4096},semio_framework_job::default_now_us,u64::MAX,1<<28);let mut decoder=OriginalJobDecodeOwner::empty();let mut typed=TypedWindowConfigStoreOwner::<Owner>::new(protocol::ActorId("original-preview-actor".into()));
  for turn_index in 0..262144{if turn(&mut caller,&mut decoder,crate::original_genesis_tests::grant(),|cx|typed.ensure_partition("original-preview-window",cx)){break;}assert!(turn_index<262143,"native Window partition birth failed to settle");}
  let partition=typed.partitions.get_mut("original-preview-window").unwrap();assert!(partition.store.owned_disposer_installed());for cut in corpus["cancelPrefixes"].as_array().unwrap(){cancelled_leaf(&partition.store,&mut caller,&mut decoder,cut.as_u64().unwrap()as usize);}let d=WindowSemanticPreview::<Owner>::birth_demand();let mut preview=turn(&mut caller,&mut decoder,grant(d),|cx|{let(owner,receipt)=WindowSemanticPreview::<Owner>::begin(&partition.store,grant(d))?.unwrap();cx.consume_retained(receipt)?;cx.consume_fuel(1);Ok(owner)});
  for leaf in law["leaves"].as_array().unwrap(){let mutation=WindowConfigMutation::of::<Owner>("original-preview-window",Mutation::Zoom{zoom:leaf.as_f64().unwrap()});let pointer=mutation.mutation.as_any().downcast_ref::<Mutation>().unwrap()as*const Mutation;let mut slot=RetainedOriginalSlot::new(mutation);let key=slot.key();let factory:Arc<dyn store::ArtifactOwnedValueRetirementFactory<WindowConfigMutation>>=Arc::new(semio_framework_value::factory::OwnedValueRetirementFactory::<WindowConfigMutation>::default());
   for index in 0..32{if slot.borrow(key).is_ok(){break;}let d=slot.demands(key).unwrap();turn(&mut caller,&mut decoder,grant(d),|cx|{let step=slot.advance_read(key,&factory,grant(d))?;cx.consume_retained(step.progress())?;cx.consume_fuel(1);Ok(())});assert!(index<31,"original Window press source birth failed");}
   let d=RetainedOwnedProjection::<WindowConfigMutation>::constructor_demand();let mut input=turn(&mut caller,&mut decoder,grant(d),|cx|{let(input,p)=slot.retain_read(key,grant(d))?;cx.consume_retained(p)?;cx.consume_fuel(1);Ok(input)});let d=WindowSemanticPreview::<Owner>::input_demand();turn(&mut caller,&mut decoder,grant(d),|cx|{let p=preview.admit_input(&input,grant(d))?.unwrap();cx.consume_retained(p)?;cx.consume_fuel(1);Ok(())});assert_eq!(slot.get().mutation.as_any().downcast_ref::<Mutation>().unwrap()as*const Mutation,pointer);
   while !input.terminal_is_empty(){let d=input.close_demand(4096).unwrap();turn(&mut caller,&mut decoder,grant(d),|cx|{semio_framework_job::close_original_retained_step(cx,d,|g|input.close_step(g))?;Ok(())});}
   for index in 0..65536{if preview.leaf_ready(){break;}let d=preview.demand(&partition.store,4096).unwrap();let funded=grant(d);for axis in 0..5{let mut denied=funded;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes-=1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes-=1,3 if d.release_bytes>0=>denied.maximum_release_bytes-=1,4 if d.depth>0=>denied.maximum_depth-=1,_=>continue}assert_eq!(advance(&mut preview,&partition.store,&mut caller,&mut decoder,denied).progress(),RetainedCloneProgress::default());}advance(&mut preview,&partition.store,&mut caller,&mut decoder,funded);assert!(index<65535,"native Window semantic leaf failed to settle");}assert!(preview.leaf_ready());typed_close(slot,&mut caller,&mut decoder);typed_close(semio_framework_value::FactoryAuthority::new(factory),&mut caller,&mut decoder);
  }
  let value=serde_json::to_value(semio_framework_value::ToValue::to_value(preview.base.as_ref().unwrap().snapshot())).unwrap();assert_eq!(value["zoom"],law["expected"]);preview.cancel();for index in 0..65536{if preview.terminal_is_empty(){break;}let d=preview.demand(&partition.store,4096).unwrap();advance(&mut preview,&partition.store,&mut caller,&mut decoder,grant(d));assert!(index<65535,"original Window preview failed to close");}assert!(preview.terminal_is_empty());
  for index in 0..65536{if typed.terminal_is_empty(){break;}{let d=typed.retirement_demands(4096).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth.max(1)};turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|typed.close_step_context(g,cx).map(|_|()).map_err(Into::into)))};assert!(index<65535,"original Window partition failed to close: {:?}",typed.retirement_demands(4096));}assert!(typed.terminal_is_empty());
  for index in 0..65536{if decoder.terminal_is_empty(){break;}let d=decoder.retirement_demands(4096).unwrap();caller.turn(grant(d),|cx|cx.with_original_retirement(|cx|{semio_framework_job::close_original_retained_step(cx,d,|g|decoder.close_step(g))?;Ok(())})).unwrap();assert!(index<65535,"original Window receiving owner failed to close");}assert!(decoder.terminal_is_empty());caller.retire(wide());
 }
}
